/**
 * git·gh·jj 명령의 출력을 값으로 읽는 순수 함수들. 명령을 부르는 쪽은 hooks module 이다.
 */

/**
 * `git status --porcelain=v2 --branch` 의 출력.
 *
 * @param {string} output
 * @returns {{branch: string | null, sha: string | null, upstream: string | null, ahead: number, behind: number,
 *   staged: number, unstaged: number, untracked: number, conflicts: number}}
 */
export function parseGitStatus(output) {
  const status = { branch: null, sha: null, upstream: null, ahead: 0, behind: 0, staged: 0, unstaged: 0, untracked: 0, conflicts: 0 };
  for (const line of output.split('\n')) {
    if (line.startsWith('# branch.oid ')) {
      const oid = line.slice('# branch.oid '.length);
      status.sha = oid === '(initial)' ? null : oid;
    } else if (line.startsWith('# branch.head ')) {
      const head = line.slice('# branch.head '.length);
      status.branch = head === '(detached)' ? null : head;
    } else if (line.startsWith('# branch.upstream ')) {
      status.upstream = line.slice('# branch.upstream '.length);
    } else if (line.startsWith('# branch.ab ')) {
      const match = /\+(\d+) -(\d+)/.exec(line);
      if (match) {
        status.ahead = Number(match[1]);
        status.behind = Number(match[2]);
      }
    } else if (line.startsWith('1 ') || line.startsWith('2 ')) {
      // XY: X 는 인덱스, Y 는 작업 트리. `.` 은 변화 없음.
      if (line[2] !== '.') status.staged += 1;
      if (line[3] !== '.') status.unstaged += 1;
    } else if (line.startsWith('u ')) {
      status.conflicts += 1;
    } else if (line.startsWith('? ')) {
      status.untracked += 1;
    }
  }
  return status;
}

/**
 * `git diff --shortstat` (또는 `jj diff --stat` 의 마지막 줄)의 삽입·삭제 줄 수. 변화가 없으면 둘 다 0.
 *
 * @param {string} output
 * @returns {{insertions: number, deletions: number}}
 */
export function parseShortstat(output) {
  const insertions = /(\d+) insertions?\(\+\)/.exec(output);
  const deletions = /(\d+) deletions?\(-\)/.exec(output);
  return { insertions: insertions ? Number(insertions[1]) : 0, deletions: deletions ? Number(deletions[1]) : 0 };
}

/**
 * 원격 URL 에서 호스트·소유자·저장소. ssh(`git@host:owner/repo.git`)와 URL 꼴을 읽는다. 못 읽으면 null.
 *
 * @param {string} url
 * @returns {{host: string, owner: string, repo: string} | null}
 */
export function parseRemoteUrl(url) {
  const match = /^(?:[a-z+]+:\/\/)?(?:[^@/]+@)?([^:/]+)[:/](.+?)\/([^/]+?)(?:\.git)?\/?$/.exec(url.trim());
  return match ? { host: match[1], owner: match[2], repo: match[3] } : null;
}

/**
 * `git remote -v` 의 출력에서 origin 과 upstream.
 *
 * @param {string} output
 * @returns {{origin: ReturnType<typeof parseRemoteUrl>, upstream: ReturnType<typeof parseRemoteUrl>}}
 */
export function parseRemotes(output) {
  const remotes = { origin: null, upstream: null };
  for (const line of output.split('\n')) {
    const [name, url] = line.split(/\s+/);
    if ((name === 'origin' || name === 'upstream') && url && !remotes[name]) remotes[name] = parseRemoteUrl(url);
  }
  return remotes;
}

/**
 * `git rev-parse --path-format=absolute --git-dir --git-common-dir --show-toplevel` 의 세 줄.
 * git-dir 이 common-dir 과 다르면 linked worktree 다.
 *
 * @param {string} output
 * @returns {{isWorktree: boolean, name: string} | null}
 */
export function parseWorktree(output) {
  const [gitDir, commonDir, toplevel] = output.split('\n').map((line) => line.trim());
  if (!gitDir || !commonDir || !toplevel) return null;
  const parts = toplevel.split('/').filter(Boolean);
  return { isWorktree: gitDir !== commonDir, name: parts[parts.length - 1] ?? toplevel };
}

/**
 * `gh pr view --json number,title,url,state,statusCheckRollup` 의 출력. PR 이 없거나 JSON 이 아니면 null.
 *
 * @param {string} output
 * @returns {{pr: {number: number, title: string, url: string, state: string},
 *   checks: {failing: number, pending: number, passing: number}} | null}
 */
export function parsePullRequest(output) {
  let json;
  try {
    json = JSON.parse(output);
  } catch {
    return null;
  }
  if (!json || typeof json.number !== 'number') return null;
  const checks = { failing: 0, pending: 0, passing: 0 };
  for (const check of Array.isArray(json.statusCheckRollup) ? json.statusCheckRollup : []) {
    // CheckRun 은 status/conclusion, StatusContext 는 state 로 온다.
    const outcome = String(check.conclusion || check.state || '').toUpperCase();
    const running = check.status && String(check.status).toUpperCase() !== 'COMPLETED';
    if (running || outcome === 'PENDING' || outcome === 'EXPECTED' || outcome === '') checks.pending += 1;
    else if (['SUCCESS', 'NEUTRAL', 'SKIPPED'].includes(outcome)) checks.passing += 1;
    else checks.failing += 1;
  }
  return { pr: { number: json.number, title: json.title ?? '', url: json.url ?? '', state: json.state ?? '' }, checks };
}

/**
 * `jj log -r @ --no-graph -T 'change_id.shortest(8) ++ "\n" ++ bookmarks.join(",") ++ "\n" ++ description.first_line()'`
 * 의 세 줄.
 *
 * @param {string} output
 * @returns {{revision: string, bookmarks: string[], description: string} | null}
 */
export function parseJjLog(output) {
  const [revision = '', bookmarks = '', description = ''] = output.split('\n');
  if (!revision.trim()) return null;
  return {
    revision: revision.trim(),
    bookmarks: bookmarks.split(',').map((name) => name.trim()).filter(Boolean),
    description: description.trim(),
  };
}

/**
 * macOS `vm_stat` 의 출력과 전체 메모리(바이트)에서 쓰는 메모리. 페이지 크기를 못 읽으면 null.
 *
 * @param {string} vmStat
 * @param {number} totalBytes `sysctl -n hw.memsize`
 * @returns {{usedBytes: number, totalBytes: number} | null}
 */
export function parseVmStat(vmStat, totalBytes) {
  const pageSize = /page size of (\d+) bytes/.exec(vmStat);
  const pages = (name) => {
    const match = new RegExp(`${name}:\\s+(\\d+)`).exec(vmStat);
    return match ? Number(match[1]) : 0;
  };
  if (!pageSize || !(totalBytes > 0)) return null;
  // 비어 있거나 바로 내줄 수 있는 페이지를 뺀 나머지를 «쓰는 중» 으로 본다.
  const available = (pages('Pages free') + pages('Pages inactive') + pages('Pages speculative')) * Number(pageSize[1]);
  return { usedBytes: Math.max(0, totalBytes - available), totalBytes };
}

files.scripts/lib/parse-transcript.mjs:
/**
 * 세션 트랜스크립트(JSONL)와 usage API 응답을 읽는 순수 함수들.
 *
 * 트랜스크립트는 세션을 재개했을 때 «이전까지의 합계» 를 되찾는 곳이다. 이후의 턴은 hooks module 이
 * `turn.complete` 에서 더한다.
 */

const EMPTY_USAGE = Object.freeze({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0 });

/**
 * API 가 준 usage 를 네 값으로.
 *
 * @param {object | undefined} usage `input_tokens` 등 API 철자의 usage
 * @returns {{input: number, output: number, cacheRead: number, cacheWrite: number}}
 */
export function usageOf(usage) {
  return {
    input: usage?.input_tokens ?? 0,
    output: usage?.output_tokens ?? 0,
    cacheRead: usage?.cache_read_input_tokens ?? 0,
    cacheWrite: usage?.cache_creation_input_tokens ?? 0,
  };
}

/**
 * 두 usage 의 합.
 *
 * @param {ReturnType<typeof usageOf>} a
 * @param {ReturnType<typeof usageOf>} b
 * @returns {ReturnType<typeof usageOf>}
 */
export function addUsage(a, b) {
  return {
    input: a.input + b.input,
    output: a.output + b.output,
    cacheRead: a.cacheRead + b.cacheRead,
    cacheWrite: a.cacheWrite + b.cacheWrite,
  };
}

/**
 * 트랜스크립트 전체에서 세션 이름·토큰 합계·압축 횟수·마지막 노력 수준을 읽는다.
 *
 * 한 응답은 내용 블록마다 줄이 따로 실리고 줄마다 같은 usage 가 붙는다. 요청 id 로 한 번만 센다.
 * 서브에이전트(sidechain) 줄은 메인 대화의 합계에 넣지 않는다. 깨진 줄은 건너뛴다 — 쓰는 도중의
 * 마지막 줄이 그럴 수 있다.
 *
 * @param {string} text
 * @returns {{customTitle: string | null, aiTitle: string | null, effort: string | null, compactions: number,
 *   lastResponseAt: number | null, total: ReturnType<typeof usageOf>, last: ReturnType<typeof usageOf> | null}}
 */
export function summarizeTranscript(text) {
  const summary = { customTitle: null, aiTitle: null, effort: null, compactions: 0, lastResponseAt: null, total: EMPTY_USAGE, last: null };
  const byRequest = new Map();
  for (const line of text.split('\n')) {
    if (!line) continue;
    let entry;
    try {
      entry = JSON.parse(line);
    } catch {
      continue;
    }
    if (entry.type === 'custom-title' && typeof entry.customTitle === 'string' && entry.customTitle) {
      summary.customTitle = entry.customTitle;
    } else if (entry.type === 'ai-title' && typeof entry.aiTitle === 'string' && entry.aiTitle) {
      summary.aiTitle = entry.aiTitle;
    } else if (entry.type === 'system' && entry.subtype === 'compact_boundary' && entry.isSidechain !== true) {
      summary.compactions += 1;
    } else if (entry.type === 'assistant' && entry.isSidechain !== true && entry.message?.usage) {
      const usage = usageOf(entry.message.usage);
      byRequest.set(entry.requestId ?? entry.message.id ?? entry.uuid, usage);
      summary.last = usage;
      if (typeof entry.effort === 'string') summary.effort = entry.effort;
      const at = Date.parse(entry.timestamp ?? '');
      if (!Number.isNaN(at)) summary.lastResponseAt = at;
    }
  }
  for (const usage of byRequest.values()) summary.total = addUsage(summary.total, usage);
  return summary;
}

/**
 * 세션 루트에서 트랜스크립트 폴더 이름. Claude Code 는 경로의 영숫자가 아닌 글자를 `-` 로 바꾼다.
 *
 * @param {string} root
 * @returns {string}
 */
export function projectSlug(root) {
  return root.replace(/[^a-zA-Z0-9]/g, '-');
}

/**
 * `/api/oauth/usage` 응답에서 모델별 주간 사용량과 추가 사용량. 금액은 응답의 `decimal_places`
 * (없으면 2) 만큼 내려 통화 단위로 돌려준다.
 *
 * @param {unknown} json
 * @returns {{perModel: Record<string, {percent: number, resetsAt: string | null}>,
 *   extra: {enabled: boolean, limit: number | null, used: number | null, utilization: number | null, currency: string} | null}}
 */
export function parseUsageApi(json) {
  const result = { perModel: {}, extra: null };
  if (json === null || typeof json !== 'object') return result;

  for (const limit of Array.isArray(json.limits) ? json.limits : []) {
    const name = limit?.scope?.model?.display_name;
    if (limit?.kind !== 'weekly_scoped' || typeof name !== 'string' || typeof limit.percent !== 'number') continue;
    const key = ['sonnet', 'opus', 'fable'].find((model) => name.toLowerCase().includes(model));
    if (key) result.perModel[key] = { percent: limit.percent, resetsAt: limit.resets_at ?? null };
  }
  // limits[] 로 옮겨 가기 전의 평평한 키. 새 꼴이 있으면 그쪽이 맞다.
  for (const [key, bucket] of [['sonnet', json.seven_day_sonnet], ['opus', json.seven_day_opus]]) {
    if (!result.perModel[key] && bucket && typeof bucket.utilization === 'number') {
      result.perModel[key] = { percent: bucket.utilization, resetsAt: bucket.resets_at ?? null };
    }
  }

  const extra = json.extra_usage;
  if (extra && typeof extra === 'object') {
    const scale = 10 ** (typeof extra.decimal_places === 'number' ? extra.decimal_places : 2);
    const amount = (value) => (typeof value === 'number' ? value / scale : null);
    result.extra = {
      enabled: extra.is_enabled === true,
      limit: amount(extra.monthly_limit),
      used: amount(extra.used_credits),
      utilization: typeof extra.utilization === 'number' ? extra.utilization : null,
      currency: typeof extra.currency === 'string' ? extra.currency : 'USD',
    };
  }
  return result;
}

